def transform(grid):
    g = np.array(grid)
    bg = background(g)
    m = g != bg
    comps = components(m, diagonal=True)
    n = len(comps)
    par = list(range(n))
    def f(i):
        while par[i] != i:
            i = par[i]
        return i
    for i in range(n):
        for j in range(i + 1, n):
            if min(max(abs(a - c), abs(b - d)) for a, b in comps[i] for c, d in comps[j]) <= 2:
                par[f(i)] = f(j)
    groups = {}
    for i in range(n):
        groups.setdefault(f(i), []).extend(comps[i])
    struct = max(groups.values(), key=len)
    sset = set(struct)
    y0, x0, y1, x1 = bbox(struct)

    # legend: remaining single-colour pieces -> size = number of CW quarter turns
    rest = np.zeros_like(m)
    for y, x in zip(*np.nonzero(m)):
        if (y, x) not in sset:
            rest[y, x] = True
    leg = {}
    for c in components(rest, diagonal=True):
        leg[int(g[c[0]])] = len(c)

    S = crop(g, y0, x0, y1, x1).copy()
    emit(S, "Crop the nested figure (largest cluster) out of the grid; the loose pieces are a legend.")
    out = np.full_like(S, bg)
    cols = [int(c) for c in np.unique(S) if c != bg]
    # unrotated colours first
    for col in cols:
        if leg.get(col, 0) % 4 == 0:
            out[S == col] = col
    if any(leg.get(c, 0) % 4 == 0 for c in cols):
        emit(out.copy(), "Colours without a legend piece (or a multiple of 4 turns) stay in place.")
    for col in cols:
        k = leg.get(col, 0) % 4
        if k == 0:
            continue
        out[np.rot90(S == col, -k)] = col
        emit(out.copy(), f"Colour {col}: legend piece has {leg[col]} cells, so rotate that layer {90*leg[col]} degrees clockwise.")
    emit(out, "Final figure with every layer rotated by its legend count.")
    return out
